mod color;

use std::env;

use color::{format_cpp_float, parse_cxx_float, ColorConverter, RGB};

fn main() {
    let args: Vec<String> = env::args().collect();
    let mut colors = vec![
        RGB::new(0.1, 0.2, 0.3),
        RGB::new(0.4, 0.5, 0.6),
        RGB::new(0.7, 0.2, 0.1),
        RGB::new(0.3, 0.8, 0.4),
        RGB::new(0.9, 0.1, 0.8),
    ];

    let mut index = 1;
    while index + 2 < args.len() {
        let r = parse_cxx_float(&args[index]);
        let g = parse_cxx_float(&args[index + 1]);
        let b = parse_cxx_float(&args[index + 2]);
        colors.push(RGB::new(r, g, b));
        index += 3;
    }

    for (i, rgb) in colors.iter().copied().enumerate() {
        let hsl = ColorConverter::rgb_to_hsl(rgb);
        let hsv = ColorConverter::rgb_to_hsv(rgb);
        let cmyk = ColorConverter::rgb_to_cmyk(rgb);
        let yuv = ColorConverter::rgb_to_yuv(rgb);
        let bright = ColorConverter::adjust_brightness(rgb, 1.2);
        let dark = ColorConverter::adjust_brightness(rgb, 0.8);
        let saturated = ColorConverter::adjust_saturation(rgb, 1.5);
        let gray = ColorConverter::grayscale(rgb);
        let inverted = ColorConverter::invert(rgb);

        let mut line = format!("Color {i}: ");
        push_rgb(&mut line, rgb);
        push_f32(&mut line, hsl.h);
        push_f32(&mut line, hsl.s);
        push_f32(&mut line, hsl.l);
        push_f32(&mut line, hsv.h);
        push_f32(&mut line, hsv.s);
        push_f32(&mut line, hsv.v);
        push_f32(&mut line, cmyk.c);
        push_f32(&mut line, cmyk.m);
        push_f32(&mut line, cmyk.y);
        push_f32(&mut line, cmyk.k);
        push_f32(&mut line, yuv.y);
        push_f32(&mut line, yuv.u);
        push_f32(&mut line, yuv.v);
        push_rgb(&mut line, bright);
        push_rgb(&mut line, dark);
        push_rgb(&mut line, saturated);
        push_rgb(&mut line, gray);
        push_rgb(&mut line, inverted);

        if i == colors.len() - 1 && colors.len() > 1 {
            let dist = ColorConverter::color_distance(rgb, colors[0]);
            push_f32(&mut line, dist);
        }

        println!("{line}");
    }
}

fn push_rgb(output: &mut String, rgb: RGB) {
    push_f32(output, rgb.r);
    push_f32(output, rgb.g);
    push_f32(output, rgb.b);
}

fn push_f32(output: &mut String, value: f32) {
    output.push_str(&format_cpp_float(value));
    output.push(' ');
}

